// Normalize form fields and check required inputs
const item = $input.first().json;

const requiredFields = [
  'Facility or Department',
  'Project Name',
  'Target Go Live Date',
  'Instrument or System',
  'Site and Space Readiness',
  'Electrical Readiness',
  'Network and LIS Readiness',
  'Materials and Reagents',
  'Staffing and Operator Availability',
  'Training Readiness',
  'Verification Study Readiness'
];
const optionalFields = ['Water and Drain Readiness', 'Known Open Actions'];

const clean = (v) => (v === undefined || v === null) ? '' : String(v).trim();

const data = {};
for (const f of [...requiredFields, ...optionalFields]) {
  data[f] = clean(item[f]);
}

const missingFields = requiredFields.filter((f) => data[f] === '');

const now = new Date();
const p = (n) => String(n).padStart(2, '0');
const assessmentId = `IMPL-${now.getFullYear()}${p(now.getMonth() + 1)}${p(now.getDate())}-${p(now.getHours())}${p(now.getMinutes())}${p(now.getSeconds())}`;
const submittedAt = clean(item.submittedAt) || now.toISOString();

const submissionText = [
  `Assessment ID: ${assessmentId}`,
  `Submission date: ${submittedAt.slice(0, 10)}`,
  ...[...requiredFields, ...optionalFields].map(
    (f) => `${f}: ${data[f] || 'Not clearly stated in the submission'}`
  )
].join('\n');

return [{
  json: {
    isValid: missingFields.length === 0,
    missingFields,
    assessmentId,
    submittedAt,
    facility: data['Facility or Department'],
    project: data['Project Name'],
    targetGoLive: data['Target Go Live Date'],
    instrument: data['Instrument or System'],
    submissionText
  }
}];

// Flatten the AI assessment and prepare one row per open action
const ai = $input.first().json.output || {};
const base = $('Normalize and Validate').first().json;

const allowedStatus = ['Ready', 'Conditionally Ready', 'Not Ready'];
const allowedCriticality = ['Critical', 'High', 'Medium', 'Low'];
const notStated = 'Not clearly stated in the submission';

// Fail-safe: an unapproved status is treated as Not Ready so a human reviews it.
const readinessStatus = allowedStatus.includes(ai.readinessStatus) ? ai.readinessStatus : 'Not Ready';
const score = Math.round(Number(ai.readinessScore));
const readinessScore = Number.isFinite(score) ? Math.max(0, Math.min(100, score)) : 0;

const rawActions = Array.isArray(ai.openActions) ? ai.openActions : [];
const actions = rawActions.map((a, i) => ({
  'Assessment ID': base.assessmentId,
  'Action ID': `${base.assessmentId}-A${String(i + 1).padStart(2, '0')}`,
  'Requirement Area': a.requirementArea || notStated,
  'Missing Item': a.missingItem || notStated,
  'Owner Role': a.ownerRole || 'Other',
  'Target Date': a.targetDate || '',
  'Criticality': allowedCriticality.includes(a.criticality) ? a.criticality : 'Medium',
  'Status': 'Open',
  'Evidence Needed': a.evidenceNeeded || notStated
}));

const criticalGaps = Array.isArray(ai.criticalGaps) ? ai.criticalGaps.map(String) : [];
const summary = ai.summary || notStated;

// Routing: Not Ready always drafts; Conditionally Ready drafts only when a High or Critical gap exists.
const hasHighGap = actions.some((a) => a.Criticality === 'Critical' || a.Criticality === 'High');
const needsDraft = readinessStatus === 'Not Ready' || (readinessStatus === 'Conditionally Ready' && hasHighGap);
const draftType = readinessStatus === 'Not Ready' ? 'Escalation' : 'Follow-up';

const draftSubject = `DRAFT ${draftType}: ${base.facility} - ${base.project} - ${readinessStatus}`;

const draftBody = [
  'Hello,',
  '',
  `This is a DRAFT ${draftType.toLowerCase()} message for human review. It was prepared from a fictional portfolio demonstration and has not been sent.`,
  '',
  `Assessment ID: ${base.assessmentId}`,
  `Facility: ${base.facility}`,
  `Project: ${base.project}`,
  `Target go-live: ${base.targetGoLive}`,
  `Preliminary readiness status: ${readinessStatus} (score ${readinessScore})`,
  '',
  'Summary:',
  summary,
  '',
  'Critical gaps:',
  ...(criticalGaps.length ? criticalGaps.map((g) => `- ${g}`) : ['- None identified']),
  '',
  'Open actions:',
  ...(actions.length
    ? actions.map((a) => `- [${a.Criticality}] ${a['Requirement Area']}: ${a['Missing Item']} | Owner: ${a['Owner Role']} | Target: ${a['Target Date']} | Evidence: ${a['Evidence Needed']}`)
    : ['- None']),
  '',
  'This is a preliminary administrative assessment. Human review is required before any escalation or follow-up.',
  '',
  'Regards,',
  'Implementation Readiness Demo (fictional)'
].join('\n');

return [{
  json: {
    assessmentId: base.assessmentId,
    submittedAt: base.submittedAt,
    facility: base.facility,
    project: base.project,
    targetGoLive: base.targetGoLive,
    readinessStatus,
    readinessScore,
    criticalGaps: criticalGaps.join('; ') || 'None identified',
    summary,
    humanReviewStatus: 'Pending',
    actions,
    needsDraft,
    draftType,
    draftSubject,
    draftBody
  }
}];
